Here's a fully documented TCP server implementation in C. It listens on a user-specified port, accepts a client connection, reads data sent by the client, and echoes it back.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

int main(int argc, char *argv[]) {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t addr_len = sizeof(client_addr);
    char buffer[1024];
    char ip[INET_ADDRSTRLEN]; // Buffer to store IPv4 address in string form

    // Validate command line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <port>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int port = atoi(argv[1]);

    // Create a socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Zero-initialize the server address structure
    memset(&server_addr, 0, sizeof(server_addr));

    // Configure server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;            // Accept connections from any client
    server_addr.sin_port = htons(port);                  // Convert port to network byte order

    // Bind the socket to the specified port
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        perror("bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Start listening for incoming connections
    if (listen(server_fd, 3) == -1) {
        perror("listen failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Server is listening on port %d...\n", port);

    // Main loop for accepting client connections
    while (1) {
        printf("Waiting for new client connection...\n");
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addr_len);

        if (client_fd == -1) {
            perror("accept failed");
            close(server_fd);
            exit(EXIT_FAILURE);
        }

        // Print client address and port
        inet_ntop(AF_INET, &client_addr.sin_addr, ip, INET_ADDRSTRLEN);
        printf("Client connected from %s:%d\n", ip, ntohs(client_addr.sin_port));

        // Echo loop: read data from client and echo it back
        ssize_t bytes_read;
        while ((bytes_read = read(client_fd, buffer, sizeof(buffer) - 1)) > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the received data
            printf("Received: %s\n", buffer);
            write(client_fd, buffer, bytes_read);
        }

        // Check if connection was closed or an error occurred
        if (bytes_read == 0) {
            printf("Client disconnected.\n");
        } else {
            perror("read failed");
        }

        close(client_fd);
    }

    close(server_fd); // This line is theoretically unreachable in the current design
    return 0;
}
```

